import React from 'react';import{createRoot}from'react-dom/client';
import{BotsWorkspace}from'../../app/bots/workspace';import{botsClient as client}from'../../app/bots/client';import{botComposers}from'../../app/bots/composer-service';import{getBotTimeline}from'../../app/bots/use-timeline';
const owner='synthetic-reply-owner';const bots=['A','B'].map((id,i)=>({id,name:`Bot ${id}`,extension:i+2,purpose:'Reply browser verification',slug:id,cwd:'/synthetic',threadId:`thread-${id}`,color:'#216e4e',status:'idle',archived:false,model:null,effort:null,mode:'default',preview:'',updatedAt:'2026-10-02T01:00:00Z',activeTurnId:null,queuePaused:true}));
const entry=(id,text,user=false,at=1700000100)=>({id,turnId:`turn-${id}`,type:user?'userMessage':'agentMessage',item:user?{type:'userMessage',id,clientId:`client-${id}`,content:[{type:'text',text,text_elements:[]}]}:{type:'agentMessage',id,text,phase:'final_answer',memoryCitation:null,delivery:null,questions:null},complete:true,scheduled:false,status:'completed',startedAt:at,messageAt:at,timeBasis:'received'});
const ref=(id='answer',role='assistant')=>({id:`reply:${id}`,botId:'A',threadId:'thread-A',turnId:`turn-${id}`,itemId:id,role,text:id==='older'?'Earlier 🧠 message\n第二行':'Original answer 👩🏽‍💻\nSecond line',truncated:false});
const old=entry('older','Earlier 🧠 message\n第二行',false,1700000000),oldRef=ref('older');
const entries=[...Array.from({length:28},(_,i)=>entry(`history-${i}`,`Prior message ${i}.\n\nParagraph with **normal Markdown**.`,false,1700000100+i)),entry('user','Original user message',true,1700000200),entry('answer','Original answer 👩🏽‍💻\nSecond line',false,1700000201),{...entry('sent','Follow-up with quote',true,1700000202),reply:oldRef}];
entries.push({...entry('missing-sent','A reply whose original was removed',true,1700000203),reply:{...ref('missing'),text:'Readable saved snapshot'}});
entries.push({...entry('burst','member one\n\nmember two',true,1700000204),replyMessages:[{id:'member-one',text:'member one',attachmentIds:[],createdAt:'2026-10-02T01:00:00Z',reply:ref()},{id:'member-two',text:'member two',attachmentIds:[],createdAt:'2026-10-02T01:00:01Z'}]});
entries.push({...entry('part-sent','Follow up to member two',true,1700000205),reply:{...ref('burst','user'),partId:'member-two',text:'member two'}});
const queue=[],calls=[],uploaded=[];let resolveMissing=false;client.start=()=>{};client.owner=owner;client.online=true;client.snapshot={bots,teams:[],pending:[],cursor:0,ready:true,models:[],schedules:[],runs:[],capabilities:{queueLists:1,queueRelativeMoves:1,messageReplies:1},defaults:{model:'synthetic',effort:'medium'}};
client.rpc=async(method,botId,params={},id)=>{calls.push({method,botId,params,id});if(method==='history.view')return{kind:'page',entries:botId==='A'?[...entries]:[],attachments:[],olderCursor:null,revision:'fixture',eventCursor:0,complete:true};if(method==='replies.prepare')return{reply:{...ref(params.itemId,params.itemId==='user'||params.partId?'user':'assistant'),...(params.partId?{partId:params.partId,text:params.partId==='member-one'?'member one':'member two'}:{})},nextCursor:null,unavailable:false};if(method==='replies.resolve'){await new Promise(r=>setTimeout(r,100));return resolveMissing||params.reply.itemId==='missing'?{entry:null,nextCursor:null,unavailable:true}:params.cursor?{entry:old,nextCursor:null,unavailable:false}:{entry:null,nextCursor:'next',unavailable:false};}if(method==='queue.list')return[...queue];if(method==='queueLists.list')return[];if(method==='queue.delete'){queue.splice(queue.findIndex(q=>q.id===params.id),1);return{deleted:true};}if(method==='queue.add'){const item={id,revision:1,state:'queued',input:[{type:'text',text:params.text,text_elements:[]}],attachments:(params.attachments??[]).map(id=>uploaded.find(file=>file.id===id)??botComposers.peek(owner,botId)?.draft.files.find(file=>file.remote?.id===id)?.remote),reply:params.reply};queue.push(item);return{queuedSubmission:item};}if(method==='turn.send'){entries.push({...entry(id,params.text,true,1700000300+entries.length),reply:params.reply});return{turn:{id:`turn-${id}`}};}return{};};
client.upload=async(botId,file,progress,id)=>{const attachment={id,botId,name:file.name,size:file.size,mimeType:file.type,ready:true};uploaded.push(attachment);return attachment;};
createRoot(document.getElementById('root')).render(<BotsWorkspace/>);
window.replies={calls,queue,owner,ref,composer:()=>botComposers.peek(owner,new URL(location.href).searchParams.get('bot')||'A'),draft:id=>botComposers.peek(owner,id),timeline:()=>getBotTimeline(owner,'A'),select(id){history.pushState({},'',`/review?bot=${id}`);window.dispatchEvent(new PopStateEvent('popstate'));},type(text){const field=document.querySelector('.bots-composer textarea');Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(field,text);field.dispatchEvent(new Event('input',{bubbles:true}));},async attach(){const c=this.composer();c.addFiles([new File(['file bytes'],'example.txt',{type:'text/plain'})]);await c.flush();await c.resumeUploads();},missing(value){resolveMissing=value;},async reset(){await this.timeline().dispose();}};
